The Monte-Carlo exposed the real risk: the sharp calibration directions were built from ~10-image groups, so on *held-out* images their expected advantage shrinks (pair +3.2 vs +11 deterministic) with nonpair noise. The "plain" mean-difference directions are more robust per-unit-signal but too blunt for the deep errors. The natural compromise: **mixtures** of sharp and plain directions (interpolating between error-mode calibration and the robust class-mean axis), plus optionally dropping the riskiest row-59/96 terms. I'll score all of these with the MC noise model offline, only switch (with automatic revert-to-snapshot protection) if a variant clearly beats the current verified edit:

```python
import numpy as np, torch
from collections import Counter

# rebuild the VERIFIED snapshot edit (practice pair+10, nonpair+1, overall+0.18) for safe revert
W0=sd['heads.head.weight'].to(torch.float32).numpy().astype(np.float64)
B0=sd['heads.head.bias'].to(torch.float32).numpy().astype(np.float64)
Wsnap=W0.copy(); Bsnap=B0.copy()
for c,v,g in ((47,w1,1.0),(52,w2,1.0),(59,w3,2.0),(96,w4,2.0)):
    Wsnap[c]=W0[c]+(-g*v).astype(np.float32)
Bsnap[47]+=np.float32(1.5); Bsnap[52]+=np.float32(2.5); Bsnap[59]+=np.float32(1.0); Bsnap[96]+=np.float32(1.0)

def norm(v): return v/np.linalg.norm(v)
mix={}
for a in (0.4,0.6,0.8):
    mix["mix%.1f"%a]=(norm(a*w1+(1-a)*pl1), norm(a*w2+(1-a)*pl2), w3, w4)

base=mc(SH,cur,draws=300)
print("current edit MC(300): pair %+.2f (p5 %+.0f) | nonpair %+.2f (p5 %+.0f)"%base)
res=[]
def add(tag,dd,par,r): res.append((r[0],r[1],r[2],r[3],tag,dd,par))
for tn,dd in mix.items():
    for g in (0.75,1.0,1.25):
        for b47 in (1.0,1.5,2.0):
            for net in (0.5,1.0,1.5,2.0):
                par=(g,b47,g,b47+net,0,0,0,0)
                add(tn+"/A",dd,par,mc(dd,par,draws=120))
    for g34 in (1.0,2.0):
        par=(1.0,1.5,1.0,2.5,g34,1.0,g34,1.0)
        add(tn+"/B",dd,par,mc(dd,par,draws=120))
for g34 in (0.3,0.5,0.8):
    for b59 in (0.5,1.0):
        par=(0.4,2.0,0.4,3.5,g34,b59,g34,b59)
        add("PL",PL,par,mc(PL,par,draws=120))
for par in ((1.0,1.5,1.0,2.25,0,0,0,0),(1.0,1.5,1.0,3.0,0,0,0,0),(1.0,1.5,1.0,2.5,0,0,0,0)):
    add("SH/A",SH,par,mc(SH,par,draws=120))
feas=[r for r in res if r[3]>=-8 and r[2]>=0]
feas.sort(key=lambda r:(-r[0],-r[1],-r[2]))
print("top candidates (pg,pg5,nn,nn5):")
for r in feas[:8]:
    print("  %+.2f %+.0f %+.2f %+.0f  %s par=%s"%(r[0],r[1],r[2],r[3],r[4],tuple(round(float(x),2) for x in r[6])))
