    print("finalist MC(400): pair %+.2f (p5 %+.0f) nonpair %+.2f (p5 %+.0f) [%s]"%(finals[0],finals[1],finals[2],finals[3],finals[4]))
    print("current: pair %+.2f nonpair %+.2f"%(base[0],base[2]))
    if finals[0] >= base[0]+1.5 and finals[2] >= base[2]-1.0:
        dd=finals[5]; par=finals[6]
        _,_,npred=det(dd,par)
        print("det pair conf:", dict(Counter((int(a),int(b)) for a,b in zip(labels[pm],npred[pm]))))
        Wn=W0.copy(); Bn=B0.copy()
        for (c,v,g) in ((47,dd[0],par[0]),(52,dd[1],par[1]),(59,dd[2],par[2]),(96,dd[3],par[3])):
            if g!=0: Wn[c]=W0[c]+(-g*v).astype(np.float32)
        Bn[47]+=np.float32(par[1]); Bn[52]+=np.float32(par[3]); Bn[59]+=np.float32(par[5]); Bn[96]+=np.float32(par[7])
        save_edit('heads.head.weight',torch.from_numpy(Wn).float())
        save_edit('heads.head.bias',torch.from_numpy(Bn).float())
        r2=forward(which="both")
        for k in ("original","edited"):
            rr=r2[k]; mk2=np.isin(rr["labels"],[47,52])
            print(k,"overall=%.4f pair=%.3f maple=%.3f oak=%.3f"%(rr["acc"],(rr["pred"][mk2]==rr["labels"][mk2]).mean(),
                  (rr["pred"][rr["labels"]==47]==47).mean(),(rr["pred"][rr["labels"]==52]==52).mean()))
        re_=r2["edited"]
        ap=int((re_["pred"][pm]==labels[pm]).sum())-baseP; an=int((re_["pred"][nonpair]==labels[nonpair]).sum())-baseNP
        print("new practice: pair%+d nonpair%+d overall %+.3f (snapshot: pair+10 nonpair+1 overall+0.18)"%(ap,an,(re_["acc"]-0.8838)*100))
        if ap<9 or (re_["acc"]-0.8838)*100<-0.10:
            save_edit('heads.head.weight',torch.from_numpy(Wsnap).float())
            save_edit('heads.head.bias',torch.from_numpy(Bsnap).float())
            print("REVERTED to verified snapshot")
        else:
            switched=True
    else:
        print("no clear MC winner -> keep current verified edit")
else:
    print("no feasible candidates -> keep current edit")
print("edits:", list_edits())
```

