The split-half lost the (stolen, correct) pair structure when I intersected the concatenated group. Fixing: sample halves of P and Q *separately*, and run everything (including the full-data sanity check) in one block:

```python
import numpy as np
rng=np.random.RandomState(0)
grp={"1":(EB_idx,B_idx),"2":(EA_idx,A_idx),"3":(E59_idx,Q59),"4":(E96_idx,Q96)}
def build(Pidx,Qidx,lam=0.1):
    P=H[Pidx];Q=H[Qidx];d=P.mean(0)-Q.mean(0)
    X=np.vstack([P-P.mean(0),Q-Q.mean(0)]);S=X.T@X/max(len(Pidx)+len(Qidx)-2,1);tr=np.trace(S)/768
    z=np.linalg.solve(S+lam*tr*np.eye(768),d);return z/np.linalg.norm(z)

def evalsplit(keep, gs):
    # directions from 'keep' subset (bool masks per group), evaluate on ALL practice images
    ws={k:build(grp[k][0][keep[k]], grp[k][1][keep[k]]) for k in grp}
    g1,g2,g3,g4=gs
    vals=np.stack([l47-g1*(H@ws["1"])+1.5, l52-g2*(H@ws["2"])+2.5,
                   l59-g3*(H@ws["3"])+1.0, l96-g4*(H@ws["4"])+1.0, l37, mo],1)
    ami=vals.argmax(1); npr=np.where(ami<5,five[ami],amo)
    return (int((npr[pm]==labels[pm]).sum())-baseP, int((npr[nonpair]==labels[nonpair]).sum())-baseNP)

variants={"full g=(1,1,2,2)":(1,1,2,2), "half g=(.5,.5,1,1)":(0.5,0.5,1,1), "weak g=(.25,.25,.5,.5)":(0.25,0.25,0.5,0.5)}
out={k:[] for k in variants}
for it in range(40):
    keep={}
    for k in grp:
        nP=len(grp[k][0]); nQ=len(grp[k][1])
        mP=np.zeros(nP,bool); mP[rng.permutation(nP)[:max(nP//2,2)]]=True
        mQ=np.zeros(nQ,bool); mQ[rng.permutation(nQ)[:max(nQ//2,2)]]=True
        keep[k]=(mP,mQ)
    for k,gs in variants.items(): out[k].append(evalsplit(keep,gs))
print("split-half robustness (40 random halves build the dirs; edit scored on all practice):")
for k,v in out.items():
    v=np.array(v)
    print("  %-22s pair %+.2f±%.2f (min %+d, frac>0 %.2f) | nonpair %+.2f±%.2f (min %+d)" %
          (k, v[:,0].mean(), v[:,0].std(), v[:,0].min(), (v[:,0]>0).mean(), v[:,1].mean(), v[:,1].std(), v[:,1].min()))

# sanity: full-data directions reproduce the saved edit's deterministic sim
ws={k:build(grp[k][0],grp[k][1]) for k in grp}
vals=np.stack([l47-(H@ws["1"])+1.5, l52-(H@ws["2"])+2.5, l59-2*(H@ws["3"])+1.0,
               l96-2*(H@ws["4"])+1.0, l37, mo],1)
ami=vals.argmax(1); npd=np.where(ami<5,five[ami],amo)
print("full-data det sim of saved edit: pair %+d, nonpair %+d (matches saved-verify: +10,+1 with noise)" %
      (int((npd[pm]==labels[pm]).sum())-baseP, int((npd[nonpair]==labels[nonpair]).sum())-baseNP))
